import { Pool, PoolClient } from "pg";
import { createHash } from "crypto";

export interface StoredResponse {
  status: number;
  body: unknown;
}

export interface IdempotencyRecord {
  key: string;
  customerId: string;
  requestHash: string;
  response: StoredResponse | null;
  createdAt: Date;
}

export function hashRequest(body: unknown): string {
  return createHash("sha256").update(JSON.stringify(body)).digest("hex");
}

export class IdempotencyStore {
  constructor(private readonly pool: Pool) {}

  async find(customerId: string, key: string): Promise<IdempotencyRecord | null> {
    const { rows } = await this.pool.query(
      `SELECT key, customer_id, request_hash, response, created_at
         FROM idempotency_keys
        WHERE customer_id = $1 AND key = $2`,
      [customerId, key]
    );
    if (rows.length === 0) return null;
    const r = rows[0];
    return {
      key: r.key,
      customerId: r.customer_id,
      requestHash: r.request_hash,
      response: r.response,
      createdAt: r.created_at,
    };
  }

  async save(
    client: PoolClient,
    customerId: string,
    key: string,
    requestHash: string,
    response: StoredResponse
  ): Promise<void> {
    await client.query(
      `INSERT INTO idempotency_keys (customer_id, key, request_hash, response, created_at)
       VALUES ($1, $2, $3, $4, now())`,
      [customerId, key, requestHash, JSON.stringify(response)]
    );
  }
}

import { Pool } from "pg";
import { IdempotencyStore, StoredResponse, hashRequest } from "./idempotencyStore";

export interface OrderLine {
  sku: string;
  quantity: number;
}

export interface CreateOrderRequest {
  customerId: string;
  idempotencyKey: string;
  lines: OrderLine[];
}

export class InsufficientStockError extends Error {
  constructor(public readonly sku: string) {
    super(`insufficient stock for ${sku}`);
  }
}

export class OrderService {
  constructor(
    private readonly pool: Pool,
    private readonly idempotency: IdempotencyStore
  ) {}

  async createOrder(req: CreateOrderRequest): Promise<StoredResponse> {
    const requestHash = hashRequest(req.lines);
    const existing = await this.idempotency.find(req.customerId, req.idempotencyKey);
    if (existing) {
      if (existing.requestHash !== requestHash) {
        return { status: 422, body: { error: "idempotency_key_reused" } };
      }
      return existing.response!;
    }

    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      for (const line of req.lines) {
        const { rowCount } = await client.query(
          `UPDATE inventory SET available = available - $1
            WHERE sku = $2 AND available >= $1`,
          [line.quantity, line.sku]
        );
        if (rowCount === 0) throw new InsufficientStockError(line.sku);
      }
      const { rows } = await client.query(
        `INSERT INTO orders (customer_id, status, created_at)
         VALUES ($1, 'placed', now()) RETURNING id`,
        [req.customerId]
      );
      const orderId: string = rows[0].id;
      for (const line of req.lines) {
        await client.query(
          `INSERT INTO order_lines (order_id, sku, quantity) VALUES ($1, $2, $3)`,
          [orderId, line.sku, line.quantity]
        );
      }
      const response: StoredResponse = { status: 201, body: { orderId } };
      await this.idempotency.save(client, req.customerId, req.idempotencyKey, requestHash, response);
      await client.query("COMMIT");
      return response;
    } catch (err) {
      await client.query("ROLLBACK");
      if (err instanceof InsufficientStockError) {
        return { status: 409, body: { error: "insufficient_stock", sku: err.sku } };
      }
      throw err;
    } finally {
      client.release();
    }
  }
}

import { Request, Response, NextFunction } from "express";
import { OrderService } from "./orderService";

export function createOrderHandler(orders: OrderService) {
  return async (req: Request, res: Response, next: NextFunction) => {
    const key = req.header("Idempotency-Key");
    if (!key || key.length > 128) {
      res.status(400).json({ error: "missing_or_invalid_idempotency_key" });
      return;
    }
    const lines = req.body?.lines;
    if (!Array.isArray(lines) || lines.length === 0) {
      res.status(400).json({ error: "lines_required" });
      return;
    }
    try {
      const result = await orders.createOrder({
        customerId: res.locals.customerId,
        idempotencyKey: key,
        lines,
      });
      res.status(result.status).json(result.body);
    } catch (err) {
      next(err);
    }
  };
}
